import{_ as e,o as a,c as s,a2 as i}from"./chunks/framework.BXzK3EA4.js";const r="/assets/PNL.DFIRY22U.jpeg",u=JSON.parse('{"title":"PNL Tracker","description":"","frontmatter":{},"headers":[],"relativePath":"new-features/pnl-tracker.md","filePath":"new-features/pnl-tracker.md"}'),n={name:"new-features/pnl-tracker.md"};function o(h,t,l,p,d,c){return a(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="pnl-tracker" tabindex="-1">PNL Tracker <a class="header-anchor" href="#pnl-tracker" aria-label="Permalink to &quot;PNL Tracker&quot;">​</a></h1><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>The PnL Tracker is a real-time intraday profit and loss view. It reconstructs a mark-to-market curve for the session from your tradebook and open positions, and plots it alongside a drawdown curve.</p><figure><img src="'+r+`" alt=""><figcaption></figcaption></figure><p>Open it at <code>/pnl-tracker</code>, or from the profile menu in the navigation bar.</p><h3 id="metrics" tabindex="-1">Metrics <a class="header-anchor" href="#metrics" aria-label="Permalink to &quot;Metrics&quot;">​</a></h3><p>Four figures are shown above the chart:</p><ul><li><strong>Current MTM</strong>: mark-to-market profit or loss right now.</li><li><strong>Max MTM</strong>: the highest point reached during the session, with its timestamp.</li><li><strong>Min MTM</strong>: the lowest point reached during the session, with its timestamp.</li><li><strong>Max Drawdown</strong>: the largest peak-to-trough decline in the curve.</li></ul><p>Currency formatting follows the connected broker, so a crypto account is not forced into rupee formatting.</p><h3 id="the-chart" tabindex="-1">The Chart <a class="header-anchor" href="#the-chart" aria-label="Permalink to &quot;The Chart&quot;">​</a></h3><p>Two Baseline series are drawn in <strong>separate panes</strong>, split three to one in favour of the PnL curve. Drawdown is always at or below zero and usually an order of magnitude smaller than MTM, so overlaying the two on one price scale flattened both.</p><table tabindex="0"><thead><tr><th>Series</th><th>Pane</th><th>Colour</th></tr></thead><tbody><tr><td>MTM PnL, above break-even</td><td>Upper (3 parts)</td><td>Green</td></tr><tr><td>MTM PnL, below break-even</td><td>Upper (3 parts)</td><td>Red</td></tr><tr><td>Drawdown from peak</td><td>Lower (1 part)</td><td>Amber</td></tr></tbody></table><p>The chart is built on TradingView Lightweight Charts v5 and follows the application theme, so it redraws when you switch between light and dark.</p><p>A camera control captures the metrics and the chart together as a single image for sharing or journalling.</p><h3 id="how-the-curve-is-built" tabindex="-1">How the Curve Is Built <a class="header-anchor" href="#how-the-curve-is-built" aria-label="Permalink to &quot;How the Curve Is Built&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Fetch the tradebook and the position book through the service layer</span></span>
<span class="line"><span>   (so Analyzer mode returns sandbox state, not broker state)</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>2. Fetch 1-minute historical candles for every symbol involved</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>3. Mark each trade and each open position to the candle close, minute by minute</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>4. Sum the per-symbol series into one portfolio series from 09:00 IST</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>5. Derive the drawdown series from the running peak of that curve</span></span></code></pre></div><p>For an executed trade:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> action </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;BUY&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    pnl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (current_price </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> executed_price) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> quantity</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># SELL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    pnl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (executed_price </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> current_price) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> quantity</span></span></code></pre></div><p>When the tradebook is empty but positions exist, the position&#39;s average price is used instead:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> quantity </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># long</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    pnl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (current_price </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> average_price) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> quantity</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:                 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># short</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    pnl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (average_price </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> current_price) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> abs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(quantity)</span></span></code></pre></div><p>Per-symbol series are time-aligned with a pandas join and forward-filled so a symbol with no tick in a given minute does not punch a hole in the portfolio curve.</p><h3 id="time-handling" tabindex="-1">Time Handling <a class="header-anchor" href="#time-handling" aria-label="Permalink to &quot;Time Handling&quot;">​</a></h3><ul><li>The window runs from <strong>09:00 IST</strong> to the current time, at 1-minute resolution.</li><li>Broker timestamps arrive in several shapes: epoch seconds, epoch milliseconds, and ISO strings. All three are detected and converted to <code>Asia/Kolkata</code>.</li><li>Historical fetches are paced by an internal rate limiter, because reconstructing a session for many symbols means one history call per symbol.</li></ul><h3 id="refresh-behaviour" tabindex="-1">Refresh Behaviour <a class="header-anchor" href="#refresh-behaviour" aria-label="Permalink to &quot;Refresh Behaviour&quot;">​</a></h3><p>There is <strong>no auto-refresh</strong>. Reconstructing the curve costs one tradebook call, one position-book call, and one history call per symbol, so refreshing on a timer would burn the broker&#39;s rate budget for little benefit. Use the Refresh control when you want an updated picture.</p><h3 id="analyzer-mode" tabindex="-1">Analyzer Mode <a class="header-anchor" href="#analyzer-mode" aria-label="Permalink to &quot;Analyzer Mode&quot;">​</a></h3><p>The tracker reads through the same tradebook and position-book services as the rest of Tradeboard, so in Analyzer mode it plots sandbox trades and sandbox positions. There is a separate sandbox P&amp;L view at <code>/sandbox/mypnl</code> for sandbox-specific reporting.</p><h3 id="broker-compatibility" tabindex="-1">Broker Compatibility <a class="header-anchor" href="#broker-compatibility" aria-label="Permalink to &quot;Broker Compatibility&quot;">​</a></h3><p>The tracker needs two things from the active broker: a tradebook API and 1-minute historical data. Where either is missing or incomplete, the curve degrades rather than failing:</p><table tabindex="0"><thead><tr><th>Situation</th><th>Behaviour</th></tr></thead><tbody><tr><td>No trades today</td><td>Positions alone are used, if any exist</td></tr><tr><td>No trades and no positions</td><td>Zero metrics, flat chart</td></tr><tr><td>Missing historical data for a symbol</td><td>Flat line at the current value for that symbol</td></tr><tr><td>Unparseable timestamp</td><td>Falls back to the default time range</td></tr><tr><td>Numeric field arrives as a string</td><td>Converted to float</td></tr></tbody></table><p>MCX and other lot-based commodity contracts get a special quantity path where the broker reports trade value equal to average price, which means one lot.</p><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>&quot;No data in TradeBook&quot;</td><td>Normal before your first fill. Position P&amp;L still plots if you hold something.</td></tr><tr><td>All zeros</td><td>Confirm an API key is configured at <code>/apikey</code>, that the market has been open since 09:00 IST, and that trades or positions exist.</td></tr><tr><td>Chart empty but metrics populated</td><td>The broker returned no 1-minute history for those symbols. Check the history API for one of them directly.</td></tr><tr><td>Wrong times on the axis</td><td>Conversion to IST is automatic; if it persists, the broker&#39;s timestamp format is the thing to report.</td></tr><tr><td>Screenshot fails</td><td>The capture runs in the browser. Check the browser console.</td></tr></tbody></table>`,33)])])}const g=e(n,[["render",o]]);export{u as __pageData,g as default};
